-- 1. Criar a tabela se ela ainda não existir
CREATE TABLE IF NOT EXISTS public.palavras_spelling (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    level TEXT NOT NULL,
    word TEXT NOT NULL,
    sentence TEXT,
    audio_url TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Habilitar RLS (Row Level Security) para segurança no Supabase
ALTER TABLE public.palavras_spelling ENABLE ROW LEVEL SECURITY;

-- 3. Criar política para permitir leitura pública (SELECT) por qualquer usuário/app
DROP POLICY IF EXISTS "Permitir leitura publica para palavras" ON public.palavras_spelling;
CREATE POLICY "Permitir leitura publica para palavras" 
ON public.palavras_spelling 
FOR SELECT 
USING (true);

-- 4. Limpar registros anteriores
TRUNCATE TABLE public.palavras_spelling;

